  "tutPtM5Title": "Dashboard Prestazioni & Trend",
  "tutPtM5Text": "Monitora l'andamento della partecipazione nel tempo con statistiche su chiamate, punti positivi/negativi, badge e netto.",
  "tutPtM6Title": "Storico Sessioni",
  "tutPtM6Text": "Sfoglia il registro cronologico delle sessioni con dettagli su punti individuali, squadra, badge, obiettivi e note.",
  "tutPtM7Title": "Panoramica Classe & Dettaglio Studente",
