  "lcPillPedagogy": "Obiettivo pedagogico:",
  "lcActWarmUpDesc": "Breve attività di apertura (3–5 min) per stimolare l'attenzione degli studenti, ripassare i prerequisiti e avviare la lezione.",
  "lcAct_warm_up_when": "Primi 5 minuti; routine di ingresso, recupero rapido delle conoscenze.",
  "lcActDirectInstructionDesc": "Presentazione esplicita di nuovi concetti da parte del docente, esempi guidati, regole o modellamento di procedure (10–15 min).",
  "lcAct_direct_instruction_when": "Introduzione di nuovi obiettivi di apprendimento, regole, formule o metodi.",
  "lcActGuidedPracticeDesc": "Gli studenti applicano le conoscenze appena apprese con il supporto diretto del docente, schemi guida e riscontri immediati ('Io faccio, Noi facciamo, Tu fai').",
  "lcAct_guided_practice_when": "Subito dopo la spiegazione per consolidare e correggere precocemente gli errori.",
  "lcActIndependentWorkDesc": "Gli studenti svolgono compiti, esercizi o produzioni scritte in autonomia e al proprio ritmo, senza interventi del docente.",
  "lcAct_independent_work_when": "Dopo la pratica guidata; consente all'insegnante di circolare e differenziare il supporto.",
  "lcActGroupActivityDesc": "Attività collaborativa in cui gli studenti risolvono problemi complessi, realizzano progetti o svolgono ricerche con ruoli definiti.",
  "lcAct_group_activity_when": "Ricerche a più fasi, cooperative learning, progetti creativi e compiti di realtà.",
  "lcActDiscussionDesc": "Dialogo guidato, cerchio socratico o dibattito in cui gli studenti argomentano idee, ascoltano e confrontano punti di vista.",
  "lcAct_discussion_when": "Analisi critica, dilemmi etici, interpretazione di testi e sviluppo delle competenze orali.",
  "lcActAssessmentDesc": "Verifica formativa rapida (quiz lampo, lavagnette, sondaggio) per valutare il livello di comprensione e colmare eventuali lacune.",
  "lcAct_assessment_when": "Punto di controllo a metà lezione o prima di passare a un argomento successivo.",
  "lcActPlenaryDesc": "Conclusione della lezione (5–10 min) per sintetizzare i punti chiave, verificare l'obiettivo e raccogliere i biglietti di uscita.",
  "lcAct_plenary_when": "Ultimi 5–10 minuti per consolidare quanto appreso e pianificare il lavoro successivo.",
  "lcModeWholeClassDesc": "Tutti gli studenti partecipano insieme come un'unica comunità (es. lettura condivisa, visione di filmati, brainstorming plenario).",
  "lcMode_whole_class_when": "Punto di riferimento comune, istruzioni generali, visione di contenuti o routine.",
  "lcModeTeacherLedDesc": "Il docente conduce l'attività alla cattedra o alla lavagna, spiegando i concetti e guidando le interazioni.",
  "lcMode_teacher_led_when": "Spiegazione diretta, dimostrazione pratica di procedimenti o regole complesse.",
  "lcModeIndividualDesc": "Ogni studente lavora singolarmente e in silenzio al proprio posto, favorendo concentrazione e responsabilità individuale.",
  "lcMode_individual_when": "Lettura silenziosa, scrittura personale, esercizi di consolidamento o verifiche.",
  "lcModePairsDesc": "Gli studenti collaborano a coppie (Think-Pair-Share, revisione tra pari, dialoghi). Massimizza il tempo di produzione verbale.",
  "lcMode_pairs_when": "Confronto rapido, correzione reciproca, dialoghi in lingua straniera.",
  "lcModeSmallGroupsDesc": "Piccoli gruppi di 3-4 studenti collaborano con ruoli attribuiti (portavoce, custode del tempo, verbalizzatore, coordinatore).",
  "lcMode_small_groups_when": "Progetti cooperativi, realizzazione di presentazioni o cartelloni, compiti complessi.",
  "lcModeStationsDesc": "L'aula è divisa in postazioni di lavoro temporizzate; i gruppi ruotano da una stazione all'altra.",
  "lcMode_stations_when": "Laboratori a rotazione, esperimenti scientifici, stazioni di differenziazione e recupero.",
