  "app_classManagement_title": "Gestione Classe",
  "app_classManagement_desc": "Gestisci i gruppi classe, registra la partecipazione ed esporta i dati delle sessioni per le singole classi.",
  "app_participationTracker_title": "Registro Partecipazione",
