  "app_manageDatabase_title": "Gestisci Database",
  "app_manageDatabase_desc": "Crea e modifica banche lessicali personalizzate, dettati, banche grammaticali, storie e contenuti per quiz.",
  "app_generalConfig_title": "Configurazione Generale",
